fn binary_to_decimal(b: i64) -> i64 {
    x: i64 = b;
    r: i64 = 0;
    p: i64 = 1;
    while x > 0 {
        r = r + (x % 10) * p;
        p = p * 2;
        x = x / 10;
    }
    return r;
}
